export default "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"robots\" content=\"noindex\">\n<link rel=\"icon\" href=\"data:,\">\n<title>Traffic · __SITE_NAME__</title>\n<style>\n  [hidden]{display:none!important}\n  /* First on purpose: any author display rule, like .row{display:grid}, would otherwise beat the browser's own [hidden]. */\n  :root{--paper:#faf8f4;--paper-dim:#f1ede4;--ink:#1c1a17;--soft:#5a544c;--faint:#8a8378;--line:#e3ddd0;--green:#3f5d45;--red:#c1272d;--bar:#d9d2c3;--accent:#1c1a17}\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--paper);color:var(--ink);font:14px/1.5 system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif;-webkit-font-smoothing:antialiased}\n  a{color:inherit}\n  button,input,select{font:inherit;color:inherit}\n  .top{display:flex;flex-wrap:wrap;gap:.75rem 1.25rem;align-items:center;padding:1rem 1.5rem;border-bottom:1px solid var(--line);background:var(--paper);position:sticky;top:0;z-index:2}\n  .brand{font-weight:600;letter-spacing:.01em}\n  .brand span{font-weight:400;color:var(--soft)}\n  .live{display:flex;align-items:center;gap:.4rem;color:var(--soft)}\n  .live b{color:var(--ink)}\n  .live::before{content:\"\";width:.5rem;height:.5rem;border-radius:50%;background:var(--green)}\n  .live.quiet::before{background:var(--faint)}\n  .ranges{display:flex;flex-wrap:wrap;gap:.25rem;margin-left:auto;align-items:center}\n  .ranges button,.ranges input,.top form button,.export{background:#fff;border:1px solid var(--line);border-radius:4px;padding:.35rem .6rem;cursor:pointer;text-decoration:none;font-size:13px}\n  .ranges button[aria-pressed=\"true\"]{background:var(--ink);color:var(--paper);border-color:var(--ink)}\n  .ranges .custom{display:flex;gap:.25rem;align-items:center;margin-left:.5rem}\n  main{padding:1.5rem;max-width:1440px;margin:0 auto}\n  .kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(125px,1fr));gap:.75rem;margin-bottom:1rem}\n  .kpi{background:#fff;border:1px solid var(--line);border-radius:6px;padding:.9rem 1rem}\n  .kpi .l{color:var(--soft);font-size:12px;text-transform:uppercase;letter-spacing:.06em}\n  .kpi .v{font-size:1.6rem;font-weight:500;line-height:1.2;margin:.2rem 0}\n  .kpi .d{font-size:12px;color:var(--faint)}\n  .kpi .d.up{color:var(--green)} .kpi .d.down{color:var(--red)}\n  .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:1rem;grid-auto-flow:dense}\n  .panel{background:#fff;border:1px solid var(--line);border-radius:6px;padding:1rem 1.1rem;min-width:0}\n  .panel.wide{grid-column:1/-1}\n  .panel h2{font-size:13px;font-weight:600;margin:0 0 .6rem;display:flex;align-items:baseline;gap:.6rem}\n  .panel h2 small{font-weight:400;color:var(--faint);margin-left:auto;font-size:12px}\n  .tabs{display:flex;gap:.2rem;margin-bottom:.5rem}\n  .tabs button{background:none;border:0;border-bottom:2px solid transparent;padding:.2rem .4rem;cursor:pointer;color:var(--soft);font-size:13px}\n  .tabs button[aria-selected=\"true\"]{border-color:var(--ink);color:var(--ink)}\n  .list{margin:0;padding:0;list-style:none}\n  .row{display:grid;grid-template-columns:1fr auto auto;gap:.75rem;align-items:center;padding:.3rem 0;position:relative;font-size:13px}\n  .row .k{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;position:relative;z-index:1;padding:.15rem .4rem;min-width:0}\n  .row .k a{text-decoration:none}\n  .row .k a:hover{text-decoration:underline}\n  .row .bar{position:absolute;left:0;top:.3rem;bottom:.3rem;background:var(--paper-dim);border-radius:3px;z-index:0}\n  .row .n{font-variant-numeric:tabular-nums;color:var(--ink);z-index:1;min-width:2.5rem;text-align:right}\n  .row .m{font-variant-numeric:tabular-nums;color:var(--faint);z-index:1;min-width:2.5rem;text-align:right;font-size:12px}\n  .head{display:grid;grid-template-columns:1fr auto auto;gap:.75rem;font-size:11px;color:var(--faint);text-transform:uppercase;letter-spacing:.06em;padding:0 .4rem .3rem}\n  .row.four,.head.four{grid-template-columns:1fr auto auto auto}\n  .row.four .m,.head.four span:nth-child(n+3){min-width:4.5rem}\n  [data-paged]{display:flex;flex-direction:column}\n  .pager{display:flex;align-items:center;justify-content:flex-end;gap:.5rem;margin-top:auto;padding-top:.6rem;font-size:12px;color:var(--faint);font-variant-numeric:tabular-nums}\n  .pager button{background:#fff;border:1px solid var(--line);border-radius:4px;width:1.7rem;height:1.7rem;padding:0;cursor:pointer;color:var(--soft);font-size:16px;line-height:1}\n  .pager button:hover:not(:disabled){color:var(--ink);border-color:var(--soft)}\n  .pager button:disabled{opacity:.35;cursor:default}\n  .empty{color:var(--faint);font-size:13px;padding:.4rem}\n  .chart{width:100%;height:240px;display:block}\n  .chart .grid line{stroke:var(--line);stroke-width:1}\n  .chart text{font-size:11px;fill:var(--faint)}\n  .chart .views{fill:none;stroke:var(--faint);stroke-width:1.5}\n  .chart .visitors{fill:none;stroke:var(--ink);stroke-width:2}\n  .chart .area{fill:var(--paper-dim)}\n  .chart .cursor{stroke:var(--ink);stroke-width:1;stroke-dasharray:2 3;opacity:0}\n  .legend{display:flex;gap:1rem;font-size:12px;color:var(--soft);margin-top:.4rem}\n  .legend i{display:inline-block;width:1rem;height:0;border-top:2px solid var(--ink);vertical-align:middle;margin-right:.3rem}\n  .legend i.views{border-top:1.5px solid var(--faint)}\n  .tip{position:absolute;pointer-events:none;background:var(--ink);color:var(--paper);padding:.35rem .5rem;border-radius:4px;font-size:12px;white-space:nowrap;transform:translate(-50%,-115%);opacity:0;transition:opacity .1s}\n  .heat{display:grid;grid-template-columns:2.2rem repeat(24,1fr);gap:2px;font-size:10px;color:var(--faint)}\n  .heat>*{min-width:0}\n  @media (min-width:900px){.panel.two{grid-column:span 2}}\n  .heat .c{aspect-ratio:1;border-radius:2px;background:var(--ink)}\n  .heat .lab{display:flex;align-items:center}\n  .heat .h{text-align:center}\n  table{width:100%;border-collapse:collapse;font-size:13px}\n  td,th{text-align:left;padding:.3rem .4rem;border-bottom:1px solid var(--line);vertical-align:top}\n  th{font-weight:500;color:var(--faint);font-size:11px;text-transform:uppercase;letter-spacing:.06em}\n  td:first-child,th:first-child,td:last-child,th:last-child{white-space:nowrap}\n  .note{color:var(--faint);font-size:12px;max-width:70ch;margin:1.5rem 0 0}\n  .flag{margin-right:.35rem}\n  .status{padding:2rem;color:var(--soft)}\n  @media (max-width:640px){main{padding:1rem}.top{padding:.75rem 1rem}.ranges{margin-left:0}}\n</style>\n</head>\n<body>\n<header class=\"top\">\n  <div class=\"brand\">__SITE_NAME__ <span>traffic</span></div>\n  <div class=\"live quiet\" id=\"live\">…</div>\n  <nav class=\"ranges\" id=\"ranges\" aria-label=\"Range\">\n    <button data-range=\"today\">Today</button>\n    <button data-range=\"yesterday\">Yesterday</button>\n    <button data-range=\"7d\">7 days</button>\n    <button data-range=\"30d\" aria-pressed=\"true\">30 days</button>\n    <button data-range=\"90d\">90 days</button>\n    <button data-range=\"12m\">12 months</button>\n    <button data-range=\"all\">All</button>\n    <span class=\"custom\"><input type=\"date\" id=\"from\" aria-label=\"From\"> <span>-</span> <input type=\"date\" id=\"to\" aria-label=\"To\"> <button id=\"apply\">Apply</button></span>\n  </nav>\n  <a class=\"export\" id=\"export\" href=\"#\" download>Export CSV</a>\n  <form method=\"post\" action=\"__PREFIX__/logout\"><button type=\"submit\">Log out</button></form>\n</header>\n<main id=\"main\"><p class=\"status\">Loading…</p></main>\n<div class=\"tip\" id=\"tip\"></div>\n<script id=\"analytics-config\" type=\"application/json\">__ANALYTICS_CONFIG__</script>\n<script>\n(() => {\n  const $ = (sel, el = document) => el.querySelector(sel);\n  const main = $('#main');\n  // Per-site configuration, injected by the Worker when it serves this page.\n  const CONFIG = JSON.parse($('#analytics-config').textContent);\n  const PREFIX = CONFIG.prefix;\n  const tz = -new Date().getTimezoneOffset();\n  const LAUNCH = CONFIG.launchDate ? new Date(`${CONFIG.launchDate}T00:00:00`) : null;\n  let state = { range: '30d', from: 0, to: 0 };\n  let titles = new Map();\n  let names;\n  try { names = new Intl.DisplayNames(['en'], { type: 'region' }); } catch { names = null; }\n\n  const startOfDay = (d) => { const x = new Date(d); x.setHours(0, 0, 0, 0); return x; };\n  const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x; };\n  const unix = (d) => Math.floor(d.getTime() / 1000);\n  const fmtN = (n) => n.toLocaleString('en-GB');\n  const fmtPct = (n) => `${Math.round(n * 100)}%`;\n  const fmtDur = (s) => s < 60 ? `${Math.round(s)}s` : `${Math.floor(s / 60)}m ${Math.round(s % 60)}s`;\n  const esc = (t) => String(t).replace(/[&<>\"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));\n  const flag = (cc) => /^[A-Z]{2}$/.test(cc) ? String.fromCodePoint(...[...cc].map((c) => 0x1f1e6 + c.charCodeAt(0) - 65)) : '';\n  const country = (cc) => {\n    if (!cc || cc === '??') return 'Unknown';\n    try { return names ? names.of(cc) : cc; } catch { return cc; }\n  };\n\n  function rangeFor(key) {\n    const now = new Date();\n    const today = startOfDay(now);\n    const to = unix(now) + 60;\n    switch (key) {\n      case 'today': return { from: unix(today), to };\n      case 'yesterday': return { from: unix(addDays(today, -1)), to: unix(today) };\n      case '7d': return { from: unix(addDays(today, -6)), to };\n      case '30d': return { from: unix(addDays(today, -29)), to };\n      case '90d': return { from: unix(addDays(today, -89)), to };\n      case '12m': { const x = new Date(today); x.setMonth(x.getMonth() - 12); return { from: unix(x), to }; }\n      // Without a launch date, \"All\" is the longest range the API allows.\n      case 'all': return { from: unix(LAUNCH || addDays(today, -(5 * 366 - 2))), to };\n    }\n    return null;\n  }\n\n  function setRange(key, from, to) {\n    state = { range: key, from, to };\n    for (const b of document.querySelectorAll('[data-range]')) b.setAttribute('aria-pressed', String(b.dataset.range === key));\n    $('#from').value = new Date(from * 1000).toLocaleDateString('sv');\n    $('#to').value = new Date((to - 1) * 1000).toLocaleDateString('sv');\n    $('#export').href = `${PREFIX}/export.csv?from=${from}&to=${to}`;\n    load();\n  }\n\n  for (const b of document.querySelectorAll('[data-range]')) {\n    b.addEventListener('click', () => { const r = rangeFor(b.dataset.range); setRange(b.dataset.range, r.from, r.to); });\n  }\n  $('#apply').addEventListener('click', () => {\n    const f = $('#from').valueAsDate, t = $('#to').valueAsDate;\n    if (!f || !t) return;\n    const from = unix(startOfDay(new Date(f.getUTCFullYear(), f.getUTCMonth(), f.getUTCDate())));\n    const to = unix(addDays(startOfDay(new Date(t.getUTCFullYear(), t.getUTCMonth(), t.getUTCDate())), 1));\n    if (to > from) setRange('custom', from, to);\n  });\n\n  async function loadTitles() {\n    if (!CONFIG.titlesUrl) return;\n    try {\n      const corpus = await (await fetch(CONFIG.titlesUrl)).json();\n      titles = new Map(corpus.map((w) => [w.href, w.title]));\n    } catch { /* titles are a nicety */ }\n  }\n\n  async function load() {\n    const { from, to } = state;\n    let report;\n    try {\n      const res = await fetch(`${PREFIX}/api?from=${from}&to=${to}&tz=${tz}`);\n      if (res.status === 401) { location.reload(); return; }\n      if (!res.ok) throw new Error(`${res.status}`);\n      report = await res.json();\n    } catch (e) {\n      main.innerHTML = `<p class=\"status\">Could not load the report (${esc(e.message)}).</p>`;\n      return;\n    }\n    render(report);\n  }\n\n  async function refreshLive() {\n    try {\n      const live = await (await fetch(`${PREFIX}/api/live`)).json();\n      renderLive(live);\n    } catch { /* next tick */ }\n  }\n\n  function renderLive(live) {\n    const el = $('#live');\n    el.classList.toggle('quiet', live.visitors === 0);\n    el.innerHTML = `<b>${fmtN(live.visitors)}</b>&nbsp;${live.visitors === 1 ? 'person' : 'people'} in the last 30 minutes`;\n    el.title = live.pages.map((p) => `${p.key} (${p.views})`).join('\\n');\n  }\n\n  const delta = (now, before, invert = false) => {\n    if (!before) return '<span class=\"d\">no earlier data</span>';\n    const change = (now - before) / before;\n    if (Math.abs(change) < 0.005) return '<span class=\"d\">no change</span>';\n    const good = invert ? change < 0 : change > 0;\n    return `<span class=\"d ${good ? 'up' : 'down'}\">${change > 0 ? '▲' : '▼'} ${fmtPct(Math.abs(change))} vs previous period</span>`;\n  };\n\n  function kpi(label, value, before, current, fmt = fmtN, invert = false) {\n    return `<div class=\"kpi\"><div class=\"l\">${label}</div><div class=\"v\">${fmt(current)}</div>${delta(current, before, invert)}</div>`;\n  }\n\n  function label(item, kind) {\n    const k = item.key;\n    if (kind === 'page') {\n      const t = titles.get(k);\n      return `<a href=\"${esc(k)}\" target=\"_blank\" rel=\"noopener\">${esc(t ? `${t}` : k)}</a>${t ? ` <span style=\"color:var(--faint)\">${esc(k)}</span>` : ''}`;\n    }\n    if (kind === 'country') return `<span class=\"flag\">${flag(k)}</span>${esc(country(k))}`;\n    if (kind === 'place') return `<span class=\"flag\">${flag(item.country)}</span>${esc(item.name)}<span style=\"color:var(--faint)\">, ${esc(country(item.country))}</span>`;\n    if (kind === 'host') return `<a href=\"https://${esc(k)}\" target=\"_blank\" rel=\"noopener\">${esc(k)}</a>`;\n    if (kind === 'url') return `<a href=\"${esc(k)}\" target=\"_blank\" rel=\"noopener\">${esc(k.replace(/^https?:\\/\\//, ''))}</a>`;\n    if (kind === 'lang') { try { return esc(new Intl.DisplayNames(['en'], { type: 'language' }).of(k)); } catch { return esc(k); } }\n    return esc(k);\n  }\n\n  // Ten rows a panel, however many the range holds. The rest are in the page\n  // and the arrows walk through them, so a panel never grows past ten rows and\n  // never stretches the grid row it sits in. A list of ten or fewer gets no\n  // arrows at all.\n  const PAGE = 10;\n  const pager = (count) => (count > PAGE\n    ? `<nav class=\"pager\" aria-label=\"Further rows\"><button type=\"button\" data-prev aria-label=\"Previous ${PAGE}\" disabled>‹</button><span data-pos>1-${PAGE} of ${fmtN(count)}</span><button type=\"button\" data-next aria-label=\"Next ${PAGE}\">›</button></nav>`\n    : '');\n\n  function list(items, kind, unit = 'views', second = 'visitors') {\n    if (!items.length) return '<p class=\"empty\">Nothing yet.</p>';\n    const max = Math.max(...items.map((i) => i.views));\n    const rows = items.map((i, n) => `<li class=\"row\"${n >= PAGE ? ' hidden' : ''}><span class=\"bar\" style=\"width:${(i.views / max * 100).toFixed(1)}%\"></span><span class=\"k\" title=\"${esc(i.key)}\">${label(i, kind)}</span><span class=\"n\">${fmtN(i.views)}</span><span class=\"m\">${second ? fmtN(i.visitors) : ''}</span></li>`).join('');\n    return `<div data-paged><div class=\"head\"><span></span><span>${unit}</span><span>${second}</span></div><ul class=\"list\" data-rows>${rows}</ul>${pager(items.length)}</div>`;\n  }\n\n  function panel(title, body, sub = '', cls = '') {\n    return `<section class=\"panel ${cls}\"><h2>${title}${sub ? `<small>${sub}</small>` : ''}</h2>${body}</section>`;\n  }\n\n  function tabbed(title, tabs) {\n    const id = title.replace(/\\W+/g, '-').toLowerCase();\n    const buttons = tabs.map((t, i) => `<button role=\"tab\" aria-selected=\"${i === 0}\" data-tab=\"${id}-${i}\">${t.name}</button>`).join('');\n    const bodies = tabs.map((t, i) => `<div data-tabpanel=\"${id}-${i}\" ${i ? 'hidden' : ''}>${t.body}</div>`).join('');\n    return `<section class=\"panel\"><h2>${title}</h2><div class=\"tabs\" role=\"tablist\">${buttons}</div>${bodies}</section>`;\n  }\n\n  function chart(series, bucket) {\n    if (!series.length) return '<p class=\"empty\">Nothing yet.</p>';\n    const W = 960, H = 240, L = 40, R = 12, T = 12, B = 28;\n    const max = Math.max(1, ...series.map((s) => s.pageviews));\n    const x = (i) => L + (series.length === 1 ? 0 : (i / (series.length - 1)) * (W - L - R));\n    const y = (v) => T + (1 - v / max) * (H - T - B);\n    const path = (key) => series.map((s, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)},${y(s[key]).toFixed(1)}`).join(' ');\n    const area = `${path('visitors')} L${x(series.length - 1).toFixed(1)},${y(0)} L${x(0).toFixed(1)},${y(0)} Z`;\n    const ticks = [0, 0.5, 1].map((f) => `<line x1=\"${L}\" x2=\"${W - R}\" y1=\"${y(max * f)}\" y2=\"${y(max * f)}\"/><text x=\"${L - 6}\" y=\"${y(max * f) + 4}\" text-anchor=\"end\">${fmtN(Math.round(max * f))}</text>`).join('');\n    const every = Math.ceil(series.length / 8);\n    const labels = series.map((s, i) => i % every ? '' : `<text x=\"${x(i)}\" y=\"${H - 8}\" text-anchor=\"middle\">${bucket === 'hour' ? s.t.slice(11) + ':00' : s.t.slice(5)}</text>`).join('');\n    return `<svg class=\"chart\" viewBox=\"0 0 ${W} ${H}\" preserveAspectRatio=\"none\" data-chart>\n      <g class=\"grid\">${ticks}</g><path class=\"area\" d=\"${area}\"/><path class=\"views\" d=\"${path('pageviews')}\"/><path class=\"visitors\" d=\"${path('visitors')}\"/>\n      <line class=\"cursor\" data-cursor x1=\"0\" x2=\"0\" y1=\"${T}\" y2=\"${H - B}\"/>${labels}</svg>\n      <div class=\"legend\"><span><i></i>visitors</span><span><i class=\"views\"></i>page views</span></div>`;\n  }\n\n  function heat(grid) {\n    const max = Math.max(1, ...grid.flat());\n    const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];\n    const head = `<span></span>${Array.from({ length: 24 }, (_, h) => `<span class=\"h\">${h % 3 ? '' : h}</span>`).join('')}`;\n    const rows = grid.map((r, d) => `<span class=\"lab\">${days[d]}</span>${r.map((v, h) => `<span class=\"c\" style=\"opacity:${(0.06 + 0.94 * v / max).toFixed(2)}\" title=\"${days[d]} ${h}:00, ${fmtN(v)} views\"></span>`).join('')}`).join('');\n    return `<div class=\"heat\">${head}${rows}</div>`;\n  }\n\n  // Events are listed under one panel. With one configured type it carries\n  // that type's label and description; with more, a Type column tells them apart.\n  function eventsPanel(events) {\n    if (!CONFIG.events.length) return '';\n    const one = CONFIG.events.length === 1 ? CONFIG.events[0] : null;\n    const labelOf = (type) => { const e = CONFIG.events.find((x) => x.type === type); return e ? e.label : type; };\n    const body = events.length\n      ? `<div data-paged><table><thead><tr><th>When</th>${one ? '' : '<th>Type</th>'}<th>About</th><th>From page</th></tr></thead><tbody data-rows>${events.map((e, n) => `<tr${n >= PAGE ? ' hidden' : ''}><td>${when(e.ts)}</td>${one ? '' : `<td>${esc(labelOf(e.type))}</td>`}<td>${esc(e.detail || '')}</td><td>${esc(e.path || '')}</td></tr>`).join('')}</tbody></table>${pager(events.length)}</div>`\n      : '<p class=\"empty\">None in this period.</p>';\n    return panel(one ? one.label : 'Events', body, one ? one.description : CONFIG.events.map((e) => e.label).join(', '), 'wide');\n  }\n\n  const when = (ts) => new Date(ts * 1000).toLocaleString('en-GB', { dateStyle: 'medium', timeStyle: 'short' });\n\n  // Google Search Console, when a site has switched it on (search-console.js):\n  // what people typed into Google and where they landed, ten rows a panel like\n  // the rest. Absent secret or a Google error: one panel saying so, and\n  // nothing else on the page is affected.\n  function searchList(items, kind) {\n    if (!items.length) return '<p class=\"empty\">Nothing yet.</p>';\n    const max = Math.max(1, ...items.map((i) => i.clicks));\n    const rows = items.map((i, n) => `<li class=\"row four\"${n >= PAGE ? ' hidden' : ''}><span class=\"bar\" style=\"width:${(i.clicks / max * 100).toFixed(1)}%\"></span><span class=\"k\" title=\"${esc(i.key)}\">${label(i, kind)}</span><span class=\"n\">${fmtN(i.clicks)}</span><span class=\"m\">${fmtN(i.impressions)}</span><span class=\"m\">${i.position ? Number(i.position).toFixed(1) : ''}</span></li>`).join('');\n    return `<div data-paged><div class=\"head four\"><span></span><span>clicks</span><span>impressions</span><span>position</span></div><ul class=\"list\" data-rows>${rows}</ul>${pager(items.length)}</div>`;\n  }\n\n  function searchPanels(s) {\n    if (!s) return '';\n    const note = '<p class=\"note\">From Google Search Console. Final figures arrive two to three days late and rare searches are withheld.</p>';\n    if (!s.queries.length && !s.pages.length && s.status !== 'ok') {\n      const body = s.status === 'not-connected' ? 'Not connected' : `Not available: ${esc(s.message)}`;\n      return `<div class=\"grid\">${panel('Google searches', `<p class=\"empty\" title=\"${esc(s.message || '')}\">${body}</p>`)}</div>${note}`;\n    }\n    const sub = s.status === 'error' ? `last refresh failed: ${esc(s.message)}`\n      : `${fmtN(s.totals.clicks)} clicks, ${fmtN(s.totals.impressions)} impressions${s.backfilling ? ', older months still loading' : ''}${s.lastRefresh ? `, refreshed ${when(s.lastRefresh)}` : ''}`;\n    return `<div class=\"grid\">${panel('Google searches', searchList(s.queries, 'text'), sub)}${panel('Search landing pages', searchList(s.pages, 'url'), 'where Google sent people')}</div>${note}`;\n  }\n\n  function render(r) {\n    const t = r.totals, p = r.previous;\n    const period = r.range.bucket === 'hour' ? 'by hour' : 'by day';\n    main.innerHTML = `\n      <section class=\"kpis\">\n        ${kpi('Visitors', 0, p.visitors, t.visitors)}\n        ${kpi('Page views', 0, p.pageviews, t.pageviews)}\n        ${kpi('Sessions', 0, p.sessions, t.sessions)}\n        ${kpi('Pages / session', 0, p.pagesPerSession, t.pagesPerSession, (n) => n.toFixed(2))}\n        ${kpi('Bounce rate', 0, p.bounceRate, t.bounceRate, fmtPct, true)}\n        ${kpi('Session length', 0, p.avgSessionSeconds, t.avgSessionSeconds, fmtDur)}\n        ${CONFIG.events.map((e) => kpi(e.label, 0, p.eventCounts[e.type] || 0, t.eventCounts[e.type] || 0)).join('')}\n        ${kpi('Not found', 0, p.notFound, t.notFound, fmtN, true)}\n      </section>\n      ${panel(`Visitors and page views`, chart(r.series, r.range.bucket), period, 'wide')}\n      <div class=\"grid\">\n        ${panel('Pages', list(r.pages, 'page'))}\n        ${r.prefixPanels.map((x) => panel(x.title, list(x.list, 'page'), x.description || `${x.list.length} viewed`)).join('')}\n        ${panel('Countries', list(r.countries, 'country'), `${r.countries.length}`)}\n        ${panel('Cities', list(r.cities, 'place'))}\n        ${panel('Regions', list(r.regions, 'place'))}\n        ${panel('Referrers', list(r.referrers, 'host'), 'sites that sent people')}\n        ${panel('Referring pages', list(r.referrerUrls, 'url'))}\n        ${tabbed('Campaigns', [{ name: 'Sources', body: list(r.sources, 'text') }, { name: 'Mediums', body: list(r.mediums, 'text') }, { name: 'Campaigns', body: list(r.campaigns, 'text') }])}\n        ${panel('Entry pages', list(r.entries, 'page', 'sessions'), 'where sessions began')}\n        ${panel('Exit pages', list(r.exits, 'page', 'sessions'), 'where sessions ended')}\n        ${tabbed('Devices', [{ name: 'Device', body: list(r.devices, 'text') }, { name: 'Browser', body: list(r.browsers, 'text') }, { name: 'System', body: list(r.oses, 'text') }, { name: 'Language', body: list(r.languages, 'lang') }])}\n        ${panel('When people visit', heat(r.week), 'views by weekday and hour, your local time', 'two')}\n        ${panel('Broken links', list(r.notFound, 'text'), 'pages that returned 404')}\n        ${panel('Crawlers', list(r.bots.list.map((b) => ({ key: b.name, views: b.hits })), 'text', 'hits', ''), `${fmtN(r.bots.total)} hits, not counted above`)}\n        ${eventsPanel(r.events)}\n      </div>\n      ${searchPanels(r.search)}\n      <p class=\"note\">Counted by the site's own server as pages are served, so nothing runs in visitors' browsers and no cookies are set. A visitor is one person on one day: the same person on two days counts twice. Sessions end after 30 minutes of quiet. Crawlers are counted separately and never appear as visitors. Location comes from the network address and is accurate to roughly city level. Times are shown in your own time zone.</p>`;\n\n    main.querySelectorAll('[data-paged]').forEach((box) => {\n      const nav = box.querySelector('.pager');\n      if (!nav) return;\n      const rows = [...box.querySelector('[data-rows]').children];\n      const pos = nav.querySelector('[data-pos]');\n      const prev = nav.querySelector('[data-prev]');\n      const next = nav.querySelector('[data-next]');\n      const last = Math.ceil(rows.length / PAGE) - 1;\n      let page = 0;\n      const show = () => {\n        const start = page * PAGE;\n        const end = Math.min(rows.length, start + PAGE);\n        rows.forEach((row, i) => { row.hidden = i < start || i >= end; });\n        pos.textContent = `${fmtN(start + 1)}-${fmtN(end)} of ${fmtN(rows.length)}`;\n        prev.disabled = page === 0;\n        next.disabled = page === last;\n        // A full page pins the panel's height, so a shorter last page leaves\n        // the arrows where they were rather than pulling them up under the\n        // cursor. Skipped while the panel is hidden behind a tab, when it\n        // measures zero; the next full page measures it instead.\n        if (end - start === PAGE && box.offsetHeight) box.style.minHeight = `${box.offsetHeight}px`;\n      };\n      prev.addEventListener('click', () => { if (page > 0) { page -= 1; show(); } });\n      next.addEventListener('click', () => { if (page < last) { page += 1; show(); } });\n      show();\n    });\n    main.querySelectorAll('[data-tab]').forEach((b) => b.addEventListener('click', () => {\n      const section = b.closest('.panel');\n      section.querySelectorAll('[data-tab]').forEach((x) => x.setAttribute('aria-selected', String(x === b)));\n      section.querySelectorAll('[data-tabpanel]').forEach((x) => { x.hidden = x.dataset.tabpanel !== b.dataset.tab; });\n    }));\n    hover(r.series, r.range.bucket);\n    renderLive(r.live);\n  }\n\n  function hover(series, bucket) {\n    const svg = main.querySelector('[data-chart]');\n    if (!svg) return;\n    const cursor = svg.querySelector('[data-cursor]');\n    const tip = $('#tip');\n    const W = 960, L = 40, R = 12;\n    svg.addEventListener('mousemove', (e) => {\n      const rect = svg.getBoundingClientRect();\n      const fx = ((e.clientX - rect.left) / rect.width) * W;\n      const i = Math.max(0, Math.min(series.length - 1, Math.round(((fx - L) / (W - L - R)) * (series.length - 1))));\n      const s = series[i];\n      const x = L + (series.length === 1 ? 0 : (i / (series.length - 1)) * (W - L - R));\n      cursor.setAttribute('x1', x); cursor.setAttribute('x2', x); cursor.style.opacity = 1;\n      const when = bucket === 'hour' ? `${s.t.slice(0, 10)} ${s.t.slice(11)}:00` : s.t;\n      tip.textContent = `${when}: ${fmtN(s.visitors)} visitors, ${fmtN(s.pageviews)} views`;\n      tip.style.left = `${rect.left + (x / W) * rect.width + window.scrollX}px`;\n      tip.style.top = `${rect.top + window.scrollY}px`;\n      tip.style.opacity = 1;\n    });\n    svg.addEventListener('mouseleave', () => { cursor.style.opacity = 0; tip.style.opacity = 0; });\n  }\n\n  loadTitles().then(() => { const r = rangeFor('30d'); setRange('30d', r.from, r.to); });\n  setInterval(refreshLive, 60000);\n})();\n</script>\n</body>\n</html>\n";
